(5567571, 803989, 26001, '<td valign="top">that slipped leg makes this simple(notice, i am not saying ordinary) shot extraordinary. didn''t like the blown highlights though.</td>', 'that slipped leg makes this simple(notice, i am not saying ordinary) shot extraordinary. didn''t like the blown highlights though.', '2009-07-10 00:56:22.000000', NULL, 1),
(5567573, 805463, 33769, '<td valign="top">i gave this a 10 this is a great shot -- and I predict a really kick-arse score for this-- great shapes/colors and lines in this!!!</td>', 'i gave this a 10 this is a great shot -- and I predict a really kick-arse score for this-- great shapes/colors and lines in this!!!', '2009-07-10 00:57:35.000000', NULL, 1),
(5567574, 805404, 26001, '<td valign="top">noise in the sky (high iso, i am sure) bothers me a bit but like the dynamic feel caused by diagonal composition. excellent choice.</td>', 'noise in the sky (high iso, i am sure) bothers me a bit but like the dynamic feel caused by diagonal composition. excellent choice.', '2009-07-10 00:57:45.000000', NULL, 1),
(5567578, 805017, 26001, '<td valign="top">looks like you actually cut the flower square. very very cool! i like the way square "crop" plays trick with mind.</td>', 'looks like you actually cut the flower square. very very cool! i like the way square "crop" plays trick with mind.', '2009-07-10 00:59:52.000000', NULL, 1),
(5567579, 805017, 33769, '<td valign="top">this got a 10 from me on the 1st day --- very creative; this is a very beautifully done image -- extrememly creative;  i cant wait to read about how this was done/ is that paper in the bground? printed out and then cut etc-- and the flower resting in the middle?  i hope you have details! :-)  lovely final product! :-)</td>', 'this got a 10 from me on the 1st day --- very creative; this is a very beautifully done image -- extrememly creative;  i cant wait to read about how this was done/ is that paper in the bground? printed out and then cut etc-- and the flower resting in the middle?  i hope you have details! :-)  lovely final product! :-)', '2009-07-10 00:59:58.000000', NULL, 1),
(5567584, 805470, 26001, '<td valign="top">nice and simple. impressive work with exposure. I would have titled it "<b>!</b>"</td>', 'nice and simple. impressive work with exposure. I would have titled it "!"', '2009-07-10 01:01:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5567586, 805383, 26001, '<td valign="top">beautifully simple. exposure and composition are outstanding.</td>', 'beautifully simple. exposure and composition are outstanding.', '2009-07-10 01:02:46.000000', NULL, 1),
(5567587, 804222, 26001, '<td valign="top">three butterflies on one flower...that is cool. sharpness is excellent.</td>', 'three butterflies on one flower...that is cool. sharpness is excellent.', '2009-07-10 01:03:30.000000', NULL, 1),
(5567588, 805351, 26001, '<td valign="top">i keep wanting to turn the yellow pepper ~160 degrees counter-clockwise. i like the simplicity of the shot the most. this would look really nice on a kitchen wall. just a bit dark for my taste but overall i like the photo.</td>', 'i keep wanting to turn the yellow pepper ~160 degrees counter-clockwise. i like the simplicity of the shot the most. this would look really nice on a kitchen wall. just a bit dark for my taste but overall i like the photo.', '2009-07-10 01:05:26.000000', NULL, 1),
(5567590, 804842, 26001, '<td valign="top">absolutely wonderful. one of the bests in the show.<br/>my only nitpick is the "flat" lighting caused by direct flash. that probably could have been the only lighting option in this case.</td>', 'absolutely wonderful. one of the bests in the show.my only nitpick is the "flat" lighting caused by direct flash. that probably could have been the only lighting option in this case.', '2009-07-10 01:07:33.000000', NULL, 1),
(5567592, 805299, 26001, '<td valign="top">this photo is wonderful on so many levels. it must have taken ages to prep for the shot, i am sure. well executed fantastic idea.</td>', 'this photo is wonderful on so many levels. it must have taken ages to prep for the shot, i am sure. well executed fantastic idea.', '2009-07-10 01:08:59.000000', NULL, 1),
(5567593, 805316, 26001, '<td valign="top">nice composition and clever title. i also like the way you preserved details in the shadow without overexposing highlights. nice!</td>', 'nice composition and clever title. i also like the way you preserved details in the shadow without overexposing highlights. nice!', '2009-07-10 01:09:56.000000', NULL, 1),
(5567594, 805062, 26001, '<td valign="top">excellent composition. i like the location too. i feel, this could have benefited with a little more contrast though.</td>', 'excellent composition. i like the location too. i feel, this could have benefited with a little more contrast though.', '2009-07-10 01:11:27.000000', NULL, 1),
(5567596, 805246, 26001, '<td valign="top">now that is a view. dont like "too much" sky at the top that divides the shot in two halves. otherwise a nice shot.</td>', 'now that is a view. dont like "too much" sky at the top that divides the shot in two halves. otherwise a nice shot.', '2009-07-10 01:12:40.000000', NULL, 1),
(5567599, 804763, 26001, '<td valign="top">i love this one.<br/>it is fun to see different expressions on kids faces. i also like the way you converted this "looking down" shot to a "looking up" shot. choice of small aperture to get full details of kids (especially shoes) is a perfect one. tones are beautiful and sepia conversion is immaculate too.</td>', 'i love this one.it is fun to see different expressions on kids faces. i also like the way you converted this "looking down" shot to a "looking up" shot. choice of small aperture to get full details of kids (especially shoes) is a perfect one. tones are beautiful and sepia conversion is immaculate too.', '2009-07-10 01:16:43.000000', NULL, 1),
(5567631, 805428, 93283, '<td valign="top">Neither did I... Came here to vote on some photos... um... completely lost my train of thought. Not sure what I was doing here but... ummm... Oh yeah.. voting or something... Okay, umm yeah...LOL</td>', 'Neither did I... Came here to vote on some photos... um... completely lost my train of thought. Not sure what I was doing here but... ummm... Oh yeah.. voting or something... Okay, umm yeah...LOL', '2009-07-10 02:26:32.000000', NULL, 1),
