(5568070, 804842, 40126, '<td valign="top">very nice picture but title is kind of off. gave it a good score tho.</td>', 'very nice picture but title is kind of off. gave it a good score tho.', '2009-07-10 14:37:23.000000', NULL, 1),
(5568074, 805455, 40126, '<td valign="top">a little more depth of field starting from the nose would give this beautiful shot a lot more impact.</td>', 'a little more depth of field starting from the nose would give this beautiful shot a lot more impact.', '2009-07-10 14:38:52.000000', NULL, 1),
