(5574157, 805299, 58785, '<td valign="top">Welcome back ?</td>', 'Welcome back ?', '2009-07-15 01:55:10.000000', NULL, 0),
(5574160, 805016, 68504, '<td valign="top">Very well done, and sweet new meaning to the term lensbaby.</td>', 'Very well done, and sweet new meaning to the term lensbaby.', '2009-07-15 01:56:01.000000', NULL, 0),
(5574165, 805383, 79955, '<td valign="top">Congrats on the top 10 , Erik!! Nice shot !!</td>', 'Congrats on the top 10 , Erik!! Nice shot !!', '2009-07-15 01:57:50.000000', NULL, 0),
(5574168, 805481, 68504, '<td valign="top">Mistress of titles! Lovely complexity of lines and dof.<br/><br/><i>Message edited by author 2009-07-15 01:01:41.</i></td>', 'Mistress of titles! Lovely complexity of lines and dof.', '2009-07-15 01:58:31.000000', '2009-07-15 02:01:41.000000', 0),
(5574199, 804988, 68504, '<td valign="top">Very simply scary. Well seen and composed.</td>', 'Very simply scary. Well seen and composed.', '2009-07-15 02:09:06.000000', NULL, 0),
(5574218, 805435, 68504, '<td valign="top">Fascinating. This has to be the best composition in the challenge.</td>', 'Fascinating. This has to be the best composition in the challenge.', '2009-07-15 02:15:55.000000', NULL, 0),
(5574224, 805443, 68504, '<td valign="top">We liked this at our house.</td>', 'We liked this at our house.', '2009-07-15 02:18:28.000000', NULL, 0),
(5574239, 804896, 68504, '<td valign="top">Really liked the illusion of light from within the balusters, and the way the complex details of train, track and platform are balanced with each other and against the balusters.</td>', 'Really liked the illusion of light from within the balusters, and the way the complex details of train, track and platform are balanced with each other and against the balusters.', '2009-07-15 02:22:33.000000', NULL, 0),
(5574248, 805299, 24111, '<td valign="top">adorable!</td>', 'adorable!', '2009-07-15 02:26:07.000000', NULL, 0),
(5574254, 804958, 16106, '<td valign="top">Great find Joe. A pretty magical alignment.</td>', 'Great find Joe. A pretty magical alignment.', '2009-07-15 02:27:56.000000', NULL, 0),
(5574265, 805062, 68504, '<td valign="top">Just splendid.</td>', 'Just splendid.', '2009-07-15 02:33:06.000000', NULL, 0),
(5574270, 805230, 68504, '<td valign="top">Time to learn Welsh.</td>', 'Time to learn Welsh.', '2009-07-15 02:35:04.000000', NULL, 0),
(5574278, 805360, 68504, '<td valign="top">Very interesting take on and treatment of the subject.  (I also document found corpses when they present. sfa is right, though, and you have the 17! ones to prove it).</td>', 'Very interesting take on and treatment of the subject.  (I also document found corpses when they present. sfa is right, though, and you have the 17! ones to prove it).', '2009-07-15 02:39:48.000000', NULL, 0),
(5574284, 805478, 68504, '<td valign="top">Like this a lot.  The darkness and leaf shadows take us into an even greater vertiginous dimension.</td>', 'Like this a lot.  The darkness and leaf shadows take us into an even greater vertiginous dimension.', '2009-07-15 02:43:29.000000', NULL, 0),
(5574288, 805488, 50641, '<td valign="top">I like his little blue life preserver.  Marvelous textures going on here.  I hope he found something to eat - he''s too skeeny!</td>', 'I like his little blue life preserver.  Marvelous textures going on here.  I hope he found something to eat - he''s too skeeny!', '2009-07-15 02:45:28.000000', NULL, 0),
(5574295, 804097, 68504, '<td valign="top">This is amazingly spare and bold.</td>', 'This is amazingly spare and bold.', '2009-07-15 02:50:27.000000', NULL, 0),
(5574308, 805217, 108487, '<td valign="top">Way to go! Thanks for sticking with it!</td>', 'Way to go! Thanks for sticking with it!', '2009-07-15 03:00:41.000000', NULL, 0),
(5574310, 805480, 108487, '<td valign="top">Love the bending of the lines. Very nice indeed. Go get out some more!</td>', 'Love the bending of the lines. Very nice indeed. Go get out some more!', '2009-07-15 03:02:35.000000', NULL, 0),
(5574312, 804131, 108487, '<td valign="top">Nice job! Keep that camera with you at all times!</td>', 'Nice job! Keep that camera with you at all times!', '2009-07-15 03:04:48.000000', NULL, 0),
